    public static function svg(?string $name, string $class = 'icon', int $size = 20, string $label = ''): string
    {
        $name = (string) $name;
        if (!isset(self::PATHS[$name])) {
            return '';
        }
        $aria = $label === '' ? 'aria-hidden="true"' : 'role="img" aria-label="' . e($label) . '"';
        return '<svg class="' . e($class) . '" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" ' . $aria . '>'
            . self::PATHS[$name] . '</svg>';
    }

    /** @return list<string> */
    public static function names(): array
    {
        return array_keys(self::PATHS);
    }
